-- Option A (recommended; makes MBM behave like MP, future bills balanced). Run in {MBM}; equivalent to changing the head's type in HQ's Charges screen.
UPDATE {MBM}.dbo.IQCHARGES SET Chrg_Type=5 WHERE Chrg_Id=73 AND Chrg_Type=6;
-- MP account side is repaired by HL01 (missing a/c 424 -> ROUND OFF 10119).

-- Partial auto step (only lines whose item master NOW has a valid HSN): HQ copies the item HSN into the line on save, so this is what an HQ re-save writes.
UPDATE d SET HSNCODE=LTRIM(RTRIM(i.HSNCODE)) FROM IQDoc_Delv d JOIN IQDoc_Header h ON h.Doc_Id=d.Doc_Id JOIN IQItems_Mast i ON i.Item_ID=d.Item_ID
WHERE h.Tt_Id IN (500,501,504,505,506,507,510,511,266,-2) AND d.TaxValue<>0 AND NOT (LTRIM(RTRIM(ISNULL(d.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9]' OR LTRIM(RTRIM(ISNULL(d.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9][0-9][0-9]' OR LTRIM(RTRIM(ISNULL(d.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]') AND (LTRIM(RTRIM(ISNULL(i.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9]' OR LTRIM(RTRIM(ISNULL(i.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9][0-9][0-9]' OR LTRIM(RTRIM(ISNULL(i.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]');
UPDATE d SET HSNCODE=LTRIM(RTRIM(i.HSNCODE)) FROM IQDoc_Recd d JOIN IQDoc_Header h ON h.Doc_Id=d.Doc_ID JOIN IQItems_Mast i ON i.Item_ID=d.Item_ID
WHERE h.Tt_Id IN (500,501,504,505,506,507,510,511,266,-2) AND d.TaxValue<>0 AND NOT (LTRIM(RTRIM(ISNULL(d.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9]' OR LTRIM(RTRIM(ISNULL(d.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9][0-9][0-9]' OR LTRIM(RTRIM(ISNULL(d.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]') AND (LTRIM(RTRIM(ISNULL(i.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9]' OR LTRIM(RTRIM(ISNULL(i.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9][0-9][0-9]' OR LTRIM(RTRIM(ISNULL(i.HSNCODE,''))) LIKE '[0-9][0-9][0-9][0-9][0-9][0-9][0-9][0-9]');

-- Re-points the Round Off head and its postings to the firm's single "ROUND OFF" account (MP: 10119, an HQ-created account from 2022, already used by the 5 Nov bill).
-- This is exactly what HQ would have posted had the head pointed at an existing account; amounts, sides and SR_NOs are unchanged.
DECLARE @r int = (SELECT MIN(Act_Id) FROM IQAccmst WHERE UPPER(LTRIM(RTRIM(Act_Name)))='ROUND OFF' AND Act_Cat='A' HAVING COUNT(*)=1);
IF @r IS NOT NULL
BEGIN
  UPDATE d SET Act_ID=@r FROM IQDayBook d
   WHERE NOT EXISTS (SELECT 1 FROM IQAccmst a WHERE a.Act_Id=d.Act_ID)
     AND EXISTS (SELECT 1 FROM IQDoc_Chrgs c WHERE c.Doc_id=d.Doc_ID AND c.Chrg_id=73 AND c.Act_ID=d.Act_ID);
  UPDATE c SET Act_ID=@r FROM IQDoc_Chrgs c WHERE c.Chrg_id=73 AND NOT EXISTS (SELECT 1 FROM IQAccmst a WHERE a.Act_Id=c.Act_ID);
  UPDATE c SET Act_ID=@r FROM User_IQDoc_Chrgs c WHERE c.Chrg_id=73 AND NOT EXISTS (SELECT 1 FROM IQAccmst a WHERE a.Act_Id=c.Act_ID);
  UPDATE IQCHARGES SET Act_ID=@r WHERE Chrg_Id=73 AND NOT EXISTS (SELECT 1 FROM IQAccmst a WHERE a.Act_Id=IQCHARGES.Act_ID);
END
